import sys
from threading import Thread

class Solution:
    def __init__(self, inf=None, ouf=None):
        self.inf = inf if inf is not None else sys.stdin
        self.ouf = ouf if ouf is not None else sys.stdout

    def solve(self):
        s = self.inf.readline().strip()

        def match(a, b):
            return a[0] == b[0] or a[1] == b[1]

        line = self.inf.readline().strip().split()
        res = any(match(s, it) for it in line)
        self.ouf.write("YES\n" if res else "NO\n")
        self.ouf.flush()

    def run(self):
        self.solve()

def main():
    sol = Solution()
    t = Thread(target=sol.run, name="name")
    t.start()
    t.join()

if __name__ == "__main__":
    main()

