import sys
import threading

class Solution:
    def __init__(self, inf=sys.stdin, ouf=sys.stdout):
        self.inf = inf
        self.ouf = ouf

    def solve(self):
        s = self.inf.readline().strip()

        def match(a, b):
            return a[0] == b[0] or a[1] == b[1]

        line = self.inf.readline().strip().split()
        result = any(match(s, it) for it in line)
        print("YES" if result else "NO", file=self.ouf)

    def run(self):
        self.solve()
        if self.ouf is not sys.stdout:
            self.ouf.close()

def main():
    solution = Solution()
    thread = threading.Thread(target=solution.run, name="name")
    thread.start()
    thread.join()

if __name__ == "__main__":
    main()

